function ConsultProduct({id}:any){return <div><SectionHead title={product(id)?.name||id}/><ProductIntro id={id}/><Slider label={id} review={false}/><RecentProductPhotos product={id}/><External className="solid-btn">카카오톡으로 상담하기 →</External></div>}
const VASE_KEY='dfds-show-vase-v1';let vaseVisible=false;try{vaseVisible=localStorage.getItem(VASE_KEY)==='true'}catch{}
function setVaseVisible(value:boolean){vaseVisible=value;try{localStorage.setItem(VASE_KEY,String(value))}catch{}window.dispatchEvent(new Event('dfds-catalog'));}
function useVaseVisible(){const [value,setValue]=useState(vaseVisible);useEffect(()=>{const update=()=>setValue(vaseVisible);window.addEventListener('dfds-catalog',update);return()=>window.removeEventListener('dfds-catalog',update)},[]);return value;}
function VaseSetting(){const visible=useVaseVisible();return <div className="notice"><label className="check-row"><input type="checkbox" checked={visible} onChange={e=>setVaseVisible(e.target.checked)}/>꽃 메뉴에 화병꽃이 표시</label><p>켜면 고객 화면에 바로 나타납니다. 이 브라우저에 표시 설정이 저장됩니다.</p></div>}
function Photo({ label, tone = "flower", small = false, landscape = false }: { label: string; tone?: any; small?: boolean; landscape?: boolean }) {
 if(label==='근조화환'||label==='축하화환')return <div className={`photo tone-${tone} wreath-category-photo ${label==='근조화환'?'funeral-cover':'celebration-cover'}`}><img src={cms.covers[label]?.src||(label==='근조화환'?'/api/media/public/seed/category-funeral-venue.png':'/api/media/public/seed/category-celebrate-venue.png')} alt={label} loading="lazy"/></div>;
 const item=cms.covers[label]??cover(label==='꽃바구니 대표 이미지'?'꽃바구니':label)??labelPhotos(label)[0];
 return <div className={`photo tone-${tone} ${small ? "small" : ""} ${landscape ? "landscape" : ""}`}>{item?<img src={item.src} alt={label} data-photo-path={item.path} loading="lazy"/>:<span className="photo-label">{label}<br/><small>제작사진 준비 중</small></span>}</div>;
}


function ClassPreview(){useCMS();return <ClassInquiryFrame html={classHtml} channel={kakaoLinks(cms.settings.kakao).chat}/>;}

function Slider({label,tone='flower',count=4,photos,review=true}:any){
 const images=photos??labelPhotos(label);const [index,setIndex]=useState(0);useEffect(()=>setIndex(0),[label]);
 const move=(event:any,step:number)=>{const track=event.currentTarget.closest('.catalog-gallery').querySelector('.photo-slider');const next=Math.max(0,Math.min(images.length-1,index+step));track.scrollTo({left:next*(track.firstElementChild?.getBoundingClientRect().width+10||0),behavior:'smooth'});setIndex(next)};
 return <div className="catalog-gallery" data-gallery={label}>{images.length?<><div className="gallery-toolbar"><span>{label}</span><div><button type="button" aria-label={`${label} 이전 사진`} disabled={index===0} onClick={e=>move(e,-1)}>←</button><span aria-live="polite">{index+1} / {images.length}</span><button type="button" aria-label={`${label} 다음 사진`} disabled={index===images.length-1} onClick={e=>move(e,1)}>→</button></div></div><div className="photo-slider" tabIndex={0} aria-label={`${label} 사진 모음`} onScroll={e=>{const el=e.currentTarget;const width=el.firstElementChild?.getBoundingClientRect().width||0;if(width)setIndex(Math.max(0,Math.min(images.length-1,Math.round(el.scrollLeft/(width+10)))))}}>{images.map((a:any,i:number)=><figure className="photo-slide" key={a.path}><div className={`photo tone-${tone}`}><img src={a.src} alt={`${label} 제작 예시 ${i+1}`} data-photo-path={a.path} loading="lazy"/></div><figcaption>{a.product}{a.style?' · '+(a.style.startsWith('대전')?'대전꽃백화점 스타일':'바이닐 스타일'):''}{a.size?' · '+a.size:''}</figcaption></figure>)}</div>{images.length>1&&<p className="swipe-note">사진을 좌우로 넘기거나 화살표를 눌러보세요.</p>}</>:<p className="gallery-empty">{label} 제작사진을 준비하고 있어요.</p>}{review&&<Reviews/>}</div>;
}

function Input({ label, value, setValue, type = "text", required = false, placeholder = "", help, nextStepId }: { label: string; value: string; setValue: (v: string) => void; type?: string; required?: boolean; placeholder?: string; help?: string; nextStepId?:string }) {
  const inputId=useId();
  if(type==="date")return <DatePicker label={label} value={value} setValue={(v:string)=>{setValue(v);if(nextStepId)smoothTo(nextStepId)}} required={required}/>;
  return <div className="field"><label htmlFor={inputId}>{label}{required ? " *" : ""}</label><input id={inputId} value={value} type={type} placeholder={placeholder} onChange={(e) => setValue(e.target.value)} />{help && <div className="help">{help}</div>}</div>;
}

function DeliveryDetails({id,address,setAddress,receiver,setReceiver,phone,setPhone,nextId}:any){const valid=address.trim()&&receiver.trim()&&/^0\d{8,10}$/.test(phone.replace(/\D/g,''));return <StepReveal as="section" id={id} className="order-delivery-step order-input-step"><SectionHead title="어디로 전해드릴까요?" desc="배송 주소와 받으시는 분 정보를 확인해주세요."/><DeliveryTimeNotice/><Input label="배송 주소" required value={address} setValue={setAddress} help={cms.settings.deliveryNote}/><Input label="받으시는 분 성함" required value={receiver} setValue={setReceiver}/><Input label="받으시는 분 연락처" required value={phone} setValue={setPhone}/><button type="button" className="soft-btn order-input-next" disabled={!valid} onClick={()=>smoothTo(nextId)}>배송정보 입력했어요 →</button></StepReveal>}
function Area({ label, value, setValue, placeholder = "" }: { label: string; value: string; setValue: (v: string) => void; placeholder?: string }) {
  return <div className="field"><label>{label}</label><textarea value={value} placeholder={placeholder} onChange={(e) => setValue(e.target.value)} /></div>;
}

const pickupTimes={includes:(time:string)=>pickupSlots().includes(time)};
function TimeSelect({label,value,setValue,required=true,pickupOnly=true}: {label:string;value:string;setValue:(v:string)=>void;required?:boolean;pickupOnly?:boolean}){
 const current=useCMS();const times=pickupOnly?pickupSlots():halfHourTimes;
 useEffect(()=>{if(value&&!times.includes(value))setValue('')},[pickupOnly,value,current.revision]);
 return <div><TimeButtons label={label} value={value} setValue={setValue} times={times} required={required}/>{pickupOnly&&<p className="help">픽업 가능 시간 · {cms.settings.pickupAllDay?'24시간':`${cms.settings.pickupStart}–${cms.settings.pickupEnd}`}</p>}</div>;
}

function Policy({kind,close}:any){return <div className="sheet-backdrop" onClick={close}><div className="sheet policy-sheet" onClick={e=>e.stopPropagation()}><h3>{{terms:'이용약관',privacy:'개인정보처리방침',refund:'취소·환불 안내'}[kind]}</h3><p style={{whiteSpace:'pre-wrap'}}>{cms.settings[kind]||'운영 정책을 준비하고 있습니다. 문의는 매장으로 연락해주세요.'}</p><button className="soft-btn" onClick={close}>닫기</button></div></div>}
function Privacy({checked,setChecked}:any){const [privacy,setPrivacy]=useState(false),[terms,setTerms]=useState(false);return <OrderConsents settings={cms.settings} privacy={privacy} terms={terms} onPrivacyChange={(v:boolean)=>{setPrivacy(v);setChecked(v&&terms)}} onTermsChange={(v:boolean)=>{setTerms(v);setChecked(v&&privacy)}}/>}

function ConsultSheet({close}:any){return <div className="sheet-backdrop" onClick={close}><div className="sheet" onClick={e=>e.stopPropagation()}><div className="sheet-handle"/><h3>어떤 도움이 필요하세요?</h3><p>상품선택 도움과 맞춤 제작은 카카오톡으로 상담해주세요.</p><External className="solid-btn">카카오톡 상담하기</External><button className="close-btn" onClick={close}>닫기</button></div></div>}
function Landing({ enter, consult }: { enter: () => void; consult: () => void }) {
  const [slide, setSlide] = useState(0);
  useEffect(() => { const timer = setInterval(() => setSlide((v) => (v + 1) % 3), 4000); return () => clearInterval(timer); }, []);
  const backgrounds = ["flower", "shop", "work"];
  return <section className="landing"><div className={`landing-bg ${backgrounds[slide]}`} style={{backgroundImage:`linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.60)),url(${previewAssets.landing[slide]})`,backgroundSize:"cover",backgroundPosition:"center"}} /><div className="landing-noise" /><div className="landing-content"><div className="landing-dots">{backgrounds.map((_, i) => <span key={i} className={`landing-dot ${i === slide ? "active" : ""}`} />)}</div><div className="landing-kicker">Since 2002 · Daejeon</div><h1>대전꽃백화점</h1><div className="landing-en">DAEJEON FLOWER DEPARTMENT STORE</div><div className="landing-tagline">Everyday flowers, meaningful moments.</div><div className="landing-actions"><button className="landing-btn primary" onClick={enter}>바로 주문하기</button><button className="landing-btn" onClick={consult}>카카오톡 상담하기</button></div></div></section>;
}

