export default function Home() {
 const [memberOpen,setMemberOpen]=useState(false);
 useEffect(()=>{if(new URLSearchParams(window.location.search).get('moments')==='1')setMemberOpen(true)},[]);
  const [entered, setEntered] = useState(true); const [route, setRoute] = useState<Route>({ kind: "home" }); const [consult, setConsult] = useState(false); const [visited,setVisited]=useState<Route[]>([]);
  const navigate = (next: Route) => { setVisited(a=>a.some(x=>JSON.stringify(x)===JSON.stringify(next))?a:[...a,next]);setRoute(next); window.scrollTo({ top: 0, behavior: reduceMotion()?"auto":"smooth" }); };
  const routeTitle = useMemo(() => route.kind === "main" ? route.main : route.kind === "occasion" ? route.occasion : "home", [route]);
  useEffect(()=>{document.title=memberOpen?"대전꽃백화점 · 마이페이지":routeTitle==="home"?"대전꽃백화점 · 꽃과 식물":"대전꽃백화점 · "+routeTitle},[routeTitle,memberOpen]);
  if (!entered) return <><div className="app-shell"><Landing enter={() => { setEntered(true); setTimeout(() => window.scrollTo({ top: 0 }), 0); }} consult={() => setConsult(true)} /></div>{consult && <ConsultSheet close={() => setConsult(false)} />}</>;
  return <main>{memberOpen&&<MemberPortal close={()=>setMemberOpen(false)} shop={()=>{setMemberOpen(false);navigate({kind:'main',main:'FLOWER'})}} settings={cms.settings} preview={!live} photos={{꽃다발:cover('꽃다발')?.src,꽃바구니:cover('꽃바구니')?.src}}/>}<div className="app-shell" style={{display:memberOpen?'none':undefined}}><header className="site-header"><button className="wordmark" onClick={() => navigate({ kind: "home" })}><div className="wordmark-ko">대전꽃백화점</div><div className="wordmark-en">DAEJEON FLOWER DEPARTMENT STORE</div></button><div className="header-actions"><button className="header-action" onClick={()=>{setMemberOpen(true);window.scrollTo({top:0,behavior:'auto'})}}>마이페이지</button><button className="header-action" onClick={() => setConsult(true)}>상담</button></div></header><div style={{display:route.kind === "home"?"block":"none"}}><StoreHome navigate={navigate} consult={() => setConsult(true)}/></div><div className="content" style={{display:route.kind === "home"?"none":"block"}}><button className="back-btn" onClick={() => { const panel=[...document.querySelectorAll(".route-panel")].find((p:any)=>p.style.display!=="none");const buttons=panel?.querySelectorAll("[data-step-back]");if(buttons?.length)(buttons[buttons.length-1] as HTMLElement).click();else navigate({ kind: "home" }); }}>← 뒤로가기</button>{visited.filter(x=>x.kind!=="home").map((x,i)=><StepReveal as="div" motionKey={JSON.stringify(x)===JSON.stringify(route)} className="route-panel" key={JSON.stringify(x)} style={{display:JSON.stringify(x)===JSON.stringify(route)?"block":"none"}}>{x.kind==="main"?<MainPage main={x.main}/>:x.kind==="occasion"?<OccasionPage occasion={x.occasion} navigate={navigate}/>:null}</StepReveal>)}</div>{route.kind==='home'&&<PublicPhotoJournal data={cms}/>}<Footer /></div>{consult && <ConsultSheet close={() => setConsult(false)} />}<div style={{ display: "none" }}>{routeTitle}</div></main>;
}

