let CONFIG={...defaults};try{CONFIG={...defaults,...JSON.parse(localStorage.getItem(STORAGE)||'{}')}}catch{}
// Apply the confirmed shop links and hours once to older preview settings.
try{if(localStorage.getItem('dfds-store-links-hours-20261017')!=='1'){for(const key of ['naver','naverReview','naverDirections','hours','pickupHours'])CONFIG[key]=defaults[key];localStorage.setItem(STORAGE,JSON.stringify(CONFIG));localStorage.setItem('dfds-store-links-hours-20261017','1')}}catch{}
