function waiting(what:string){alert(`${what} 실제 연결이 아직 설정되지 않았습니다. 상단 ‘관리자 미리보기’ → 더보기/설정에서 실제 주소를 입력할 수 있습니다.`)}
function track(source:string){try{const all=JSON.parse(localStorage.getItem('dfds-naver-clicks')||'{}');all[source]=(all[source]||0)+1;localStorage.setItem('dfds-naver-clicks',JSON.stringify(all))}catch{}}
function External({kind='kakao',source='',children,className='soft-btn'}:any){useCMS();const u=kind==='kakao'?kakaoLinks(cms.settings.kakao).chat:kind==='kakaoChannel'?kakaoLinks(cms.settings.kakao).home:cms.settings[kind]!==undefined?cms.settings[kind]:CONFIG[kind];return u?<a className={className} href={u} target="_blank" rel="noopener noreferrer" onClick={()=>{if(kind.startsWith('naver'))track(source||kind)}}>{children}</a>:<div className="consult-fallback"><button className={className} disabled>{kind==='kakao'?'카카오톡 상담 연결 준비 중':children}</button>{kind==='kakao'&&<a href={'tel:'+cms.settings.phone.replace(/[^+0-9]/g,'')}>전화로 문의하기 · {cms.settings.phone}</a>}</div>}

function StoreActionIcon({kind}:{kind:string}){return <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">{kind==='phone'?<path d="M7 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a15 15 0 0 1-7-7l2-2-2-5Z"/>:kind==='store'?<><path d="M4 10v11h16V10M3 10l2-7h14l2 7M3 10c2 3 4 0 4 0s2 3 5 0c3 3 5 0 5 0s2 3 4 0M9 21v-7h6v7"/></>:<><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/></>}</svg>}
function Reviews(){return <div className="review-link"><External kind={cms.settings.naverReview?'naverReview':'naver'} source="리뷰">네이버에서 더 많은 리뷰 보기 →</External><p>실제 방문자 사진과 후기를 확인해보세요.</p></div>}
function Notifications(){return <div className="notice"><b>카카오톡으로 주문·배송 알림 받기</b><p>주문확인 · 배송완료 · 배송사진 확인</p><External kind="kakaoChannel">+ 대전꽃백화점 카카오톡 채널 추가</External><small>알림톡 발송은 운영 연동 후 제공됩니다.</small></div>}
function StoreLocation(){return <section className="section" id="store-location"><SectionHead eyebrow="VISIT US" title="대전꽃백화점 오시는 길"/><External kind="naver" source="약도" className="store-map-link"><img src="/api/media/public/seed/store-location-map.png" width="1360" height="1800" alt="대전꽃백화점 약도. 가오동 584 1층, 홈플러스 대전가오점, 대전 동구청, 풍림아이원 1단지, 가오주공아파트 위치 표시. 누르면 네이버 매장정보로 이동합니다." loading="lazy"/></External><p className="map-attribution">지도 데이터 © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> · 위치 안내용으로 단순화한 약도입니다.</p><p className="section-desc">대전광역시 동구 가오동 584 1층 대전꽃백화점</p>{cms.settings.hours&&<p>영업시간 · {cms.settings.hours}</p>}{CONFIG.parking&&<p>주차 안내 · {CONFIG.parking}</p>}<nav className="location-actions store-location-actions" aria-label="매장 방문 안내"><External kind={cms.settings.naverDirections?'naverDirections':'naver'} source="길찾기" className="store-action store-action-primary"><StoreActionIcon kind="map"/><span>네이버에서 길찾기</span></External><a className="store-action" href={'tel:'+cms.settings.phone.replace(/[^+0-9]/g,'')}><StoreActionIcon kind="phone"/><span>전화하기</span></a><External kind="naver" source="매장정보" className={CONFIG.kakaoMap?'store-action':'store-action store-action-wide'}><StoreActionIcon kind="store"/><span>네이버에서 매장정보 보기</span></External>{CONFIG.kakaoMap&&<External kind="kakaoMap" className="store-action"><StoreActionIcon kind="map"/><span>카카오맵에서 보기</span></External>}</nav></section>}


function WeddingPreview(){return <div><p className="section-desc" style={{whiteSpace:'pre-line'}}>{cms.sections.WEDDING.body}</p><Slider label="웨딩" review={false}/><SectionHead eyebrow="WEDDING" title="웨딩" desc="촬영부케, 본식부케, 공간장식을 함께 준비합니다."/><div className="category-grid">{cms.products.filter((p:any)=>p.group==='WEDDING'&&p.active&&!p.categoryCode?.startsWith('CAT_')).map((p:any)=>p.id).map(x=><div className="product-card" key={x}><Photo label={x} tone="wedding"/><div className="product-name">{product(x)?.name||x}</div><External>웨딩 상담하기 →</External></div>)}</div></div>}
function AccountPanel(){return <details className="account-panel"><summary>비회원 주문 · 카카오로 시작하기</summary><SectionHead title="내 주문과 기념일" desc="회원가입 없이도 주문할 수 있어요."/><button className="kakao-login" onClick={()=>alert('카카오 로그인은 Kakao Developers 앱과 실제 도메인 연결 후 사용할 수 있습니다. 현재는 비회원 주문 화면을 체험해주세요.')}>카카오로 시작하기</button><div className="account-tabs">{['주문내역','기념일','쿠폰','배송사진'].map(t=><button className="soft-btn" key={t} onClick={()=>alert(`${t}은 로그인·주문 DB 연결 후 표시됩니다.`)}>{t}</button>)}</div></details>}
function CRM(){const [yes,setYes]=useState(false);return <div className="section"><SectionHead title="내년에도 이 날을 기억해드릴까요?"/><div className="form"><label className="check-row"><input type="checkbox" checked={yes} onChange={e=>setYes(e.target.checked)}/>[선택] 기념일 알림 및 혜택 안내 받기</label>{yes&&<><label>관계<input placeholder="예: 부모님, 연인"/></label><label>기념일 종류<select><option>생일</option><option>기념일</option><option>기타</option></select></label><label>날짜<input type="date"/></label><p>기념일 7일 전 2,000원 쿠폰과 카카오 알림을 보내드려요. 쿠폰은 기념일 당일까지 사용할 수 있어요.</p><button className="soft-btn" onClick={()=>alert('화면 확인용입니다. 기념일 정보는 저장되지 않았습니다. CRM 서버 연결 후 사용할 수 있습니다.')}>기념일 등록 화면 확인</button></>}</div></div>}
function OrderComplete(){return <div className="content"><SectionHead title="주문 완료 화면 미리보기" desc="실제 결제·주문은 진행되지 않았습니다."/><Notifications/><External kind="naver" source="픽업장소">픽업 장소 네이버에서 확인 →</External><CRM/></div>}
function InvitationImport({funeral=false,onApply}:any){const [url,setUrl]=useState('');const [stage,setStage]=useState(false);const [text,setText]=useState('');const [draft,setDraft]=useState<any>({});return <div className="notice"><b>모바일 부고장 / 청첩장 링크가 있으신가요?</b><input placeholder="링크 붙여넣기" type="url" value={url} onChange={e=>setUrl(e.target.value)}/><button className="soft-btn" onClick={()=>{if(!/^https?:\/\//i.test(url)){alert('http 또는 https 링크를 입력해주세요.');return}setStage(true)}}>정보 자동 불러오기</button>{stage&&<div className="form"><p>외부 링크 자동 추출은 서버 연결이 필요합니다. 지금은 안내문 내용을 붙여넣거나 아래 항목을 직접 입력한 뒤 확인해서 반영해주세요.</p><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="부고장·청첩장 본문 붙여넣기 (선택)"/><button className="soft-btn" onClick={()=>{const date=text.match(/(20\d{2})[.년\-/ ]+(\d{1,2})[.월\-/ ]+(\d{1,2})/);const time=text.match(/(\d{1,2}):(\d{2})/);setDraft({...draft,date:date?`${date[1]}-${date[2].padStart(2,'0')}-${date[3].padStart(2,'0')}`:'',time:time?`${time[1].padStart(2,'0')}:${time[2]}`:''})}}>붙여넣은 본문에서 날짜·시간 후보 찾기</button>{(funeral?['장례식장명','주소','빈소/호실','고인','상주','발인일']:['예식장','주소','날짜','시간','신랑/신부']).map(t=><label key={t}>{t}<input value={draft[t]||((t==='날짜'||t==='발인일')?draft.date:t==='시간'?draft.time:'')||''} onChange={e=>setDraft({...draft,[t]:e.target.value})}/></label>)}<button className="solid-btn" onClick={()=>{onApply(draft);setStage(false)}}>내용 확인 후 주문폼에 반영</button></div>}</div>}

const categories={'FLOWER':['꽃다발','꽃바구니','화병꽃이','센터피스'],'PLANT':['관엽화분','동양난','서양난',...deferredPlants],'PROPOSE':['JUST ROSE','트렁크','호텔'],'CEREMONY':['근조화환','축하화환'],'WEDDING':['촬영부케','본식부케','공간장식'],'FLOWER CLASS':['플라워 클래스']};
const inventorySeed=Object.entries(categories).flatMap(([category,names])=>names.map((name,i)=>({id:category+name,category,name,price:name==='꽃다발'?'35000':name==='동양난'?'70000':'',sizes:category==='FLOWER'?'S / M / L / XL / SPECIAL':'',best:false,active:deferredPlants.includes(name)?enabledDeferredPlants.includes(name):name!=='화병꽃이'||vaseVisible,pickup:true,delivery:true,description:'',image:''})));
function ReviewApp(){useCMS();syncManagedContent();const [view,setView]=useState(location.pathname.startsWith('/admin')||location.hash==='#admin'?'admin':'customer');return <>{!live&&view==='customer'&&<div className="review-toolbar"><button className={view==='customer'?'selected':''} onClick={()=>setView('customer')}>고객 화면</button><button className="" onClick={()=>setView('admin')}>매장 관리</button></div>}{view==='admin'?<AdminManager showCustomer={()=>setView('customer')}/>:<Home/>}</>}



let giftIntent:any=null;
let finderSelection:any=null;
function openGift(navigate:any,size?:Size,style?:FlowerStyle){giftIntent={product:'꽃다발',size:size||'',style:style||''};navigate({kind:'main',main:'FLOWER'});setTimeout(()=>window.dispatchEvent(new CustomEvent('dfds-gift',{detail:giftIntent})),30)}
const sizeMeaning:any={S:'가볍게 건네는 작은 선물',M:'축하와 감사의 마음을 전할 때',L:'조금 더 풍성하게 전하고 싶을 때',XL:'큰 꽃다발을 생각하고 있을 때',SPECIAL:'원하는 구성을 함께 정할 때'};
const budgetRanges=[{id:'30000-40000',min:30000,max:40000,label:'30,000–40,000원'},{id:'50000-70000',min:50000,max:70000,label:'50,000–70,000원'},{id:'100000-150000',min:100000,max:150000,label:'100,000–150,000원'},{id:'150000-300000',min:150000,max:300000,label:'150,000–300,000원'}];
function pricedGifts(){return cms.products.filter((p:any)=>active(p.id)&&p.mode==='order'&&sectionOpen(p.group)).flatMap((p:any)=>p.variants.filter((v:any)=>v.active&&v.price!==null).map((v:any)=>{const plant=p.group==='PLANT'&&!['동양난','서양난'].includes(p.id);return {name:p.name+(v.size?' '+v.size:''),detail:v.style||p.name,price:v.price,main:p.group,customProductId:p.custom?p.id:undefined,category:plant?'관엽화분':p.id,plant:plant?p.id:undefined,size:v.size,style:v.style,variant:p.id==='JUST ROSE'?parseInt(v.size):v.size,photo:v.style?`${p.id} · ${v.style} · ${v.size}`:p.id==='서양난'?`서양난 · 예산 · ${v.size}`:p.id==='동양난'?v.size:`${p.id} ${v.size}`,fulfillment:p.id==='꽃다발'&&v.size==='S'?'픽업 전용':p.pickup&&p.delivery?'픽업 / 배송':p.pickup?'픽업 전용':'배송 전용'};}));}

function openBudgetGift(item:any,navigate:any){finderSelection=item;if(item.main==='FLOWER'){giftIntent={product:item.category,size:item.size||'',style:item.style||''};const intent=giftIntent;navigate({kind:'main',main:'FLOWER'});setTimeout(()=>window.dispatchEvent(new CustomEvent('dfds-gift',{detail:intent})),30);return}navigate({kind:'main',main:item.main});setTimeout(()=>window.dispatchEvent(new CustomEvent('dfds-finder',{detail:item.main})),30);}
function GiftFinder({navigate,consult}:any){const [purpose,setPurpose]=useState('');const [budget,setBudget]=useState('');const [mode,setMode]=useState('');const [result,setResult]=useState(false);const range=budgetRanges.find(r=>r.id===budget);const matches=range?pricedGifts().filter(p=>p.price>=range.min&&p.price<=range.max&&!(mode==='배송'&&p.fulfillment==='픽업 전용')&&!(mode==='픽업'&&p.fulfillment==='배송 전용')).sort((a,b)=>a.price-b.price):[];return <section className="decision-card" id="gift-finder"><div className="section-label">처음 고르는 분께</div><h2>꽃 이름 대신,<br/>전하고 싶은 마음부터.</h2><p>생각한 예산 범위에 들어오는 상품을 함께 살펴보세요.</p><div className="finder-fields finder-designed"><GiftChoice kind="purpose" label="어떤 순간인가요?" value={purpose} placeholder="마음을 전할 순간을 골라주세요" options={['생일','기념일','졸업','감사','부모님 선물','나에게','개업','인사이동','프로포즈','조문'].map(x=>({value:x,label:x}))} onChange={v=>{setPurpose(v);setResult(false)}}/><GiftChoice kind="budget" label="생각한 상품 예산" value={budget} placeholder="편안한 예산을 골라주세요" options={budgetRanges.map(r=>({value:r.id,label:r.label,description:'상품 금액 기준'}))} onChange={v=>{setBudget(v);setResult(false)}}/><GiftChoice kind="receive" label="어떻게 받으실까요?" value={mode} placeholder="받으실 방법을 골라주세요" options={[{value:'픽업',label:'매장 픽업',description:'가오동 매장에서 직접'},{value:'배송',label:'배송으로 전하기',description:'받으실 분께 마음을 전해요'}]} onChange={v=>{setMode(v);setResult(false)}}/></div><button className="solid-btn" disabled={!purpose||!budget||!mode} onClick={()=>setResult(true)}>예산에 맞는 상품 보기</button>{result&&<StepReveal as="div" className="finder-result"><div className="section-label">{range?.label} · 상품 가격 기준</div><p role="status">{matches.length?`예산 범위에 맞는 상품 ${matches.length}개를 찾았어요.`:'선택한 예산과 수령 방법에 맞는 상품이 아직 없어요.'}</p>{!matches.length&&<p>S 꽃다발은 픽업 전용입니다. 예산이나 수령 방법을 바꾸거나 상담해주세요.</p>}<div className="budget-results">{matches.map((p,i)=><button className="budget-result-card" key={p.main+p.name+p.detail} data-price={p.price} onClick={()=>openBudgetGift(p,navigate)}>{labelPhotos(p.photo).length>0&&<Photo label={p.photo}/>}<div><small>{p.detail}</small><b>{p.name}</b><strong>{won(p.price)}</strong><span>{p.fulfillment}</span><span>상품 살펴보기 →</span></div></button>)}</div><p className="honest-note">가격이 확정된 상품을 표시합니다. 꽃바구니·관엽화분 등 가격 확인이 필요한 상품은 상담해주세요. 배송비·쇼핑백·추가 옵션은 별도입니다. 선택하신 용도 ‘{purpose}’는 주문 시 요청사항에 남겨주세요.</p><button className="soft-btn" onClick={consult}>내 상황에 맞는 상품 상담하기</button></StepReveal>}</section>}


const psychologyReport="<article class=\"psych-report\"><p class=\"section-label\">고객 심리 · UI/UX 재설계 근거</p><h1>꽃을 잘 고르는 사람보다,<br>마음을 잘 전하는 사람이 되고 싶다.</h1><p><strong>위 문장은 검증할 핵심 가설입니다.</strong> 대전 거주 꽃 구매자를 직접 인터뷰하거나 구매 로그를 분석한 결과가 아닙니다. ‘대전 고객은 모두 이렇다’고 일반화하지 않습니다. 아래 심리 해석은 가설이며, 화면 관찰과 일반 선물 연구를 구분했습니다.</p>\n<h2>1. 현재 화면에서 확인한 것</h2><table><tr><th>코드·화면 구조 관찰</th><th>구매에 미칠 영향 가설 / 설계 대응</th></tr><tr><td>상품 탐색과 상황 탐색을 함께 제공</td><td>상품을 정한 고객과 처음 고르는 고객 모두의 진입로가 된다. 두 경로 유지.</td></tr><tr><td>전체 화면 랜딩을 통과한 뒤 상품 탐색</td><td>급한 고객에게 한 번의 불필요한 단계일 수 있다. 새 시안은 첫 화면부터 상품과 예산 접근.</td></tr><tr><td>기존 꽃 주문은 스타일을 먼저 선택해야 가격 확인</td><td>스타일 차이를 모르는 고객이 비용을 예상하기 어렵다. 사이즈별 두 스타일 가격을 먼저 노출.</td></tr><tr><td>S/M/L별 실제 사진 대부분 미등록</td><td>핵심 목적 ‘이 가격에 어느 크기인가’가 해결되지 않는다. 일반 제작사진을 M 사진으로 오인시키지 않고, 사이즈별 검증 사진 확보를 최우선 과제로 명시.</td></tr><tr><td>스타일 소개가 자리표시 문구이고 실제 비교사진 부족</td><td>고객이 이름만으로 차이를 판단하기 어렵다. 임의의 스타일 성격은 붙이지 않는다.</td></tr><tr><td>배송비·가능 일정은 확정 전, 외부 리뷰·지도 URL도 미입력</td><td>결정 마지막 단계에서 불확실성이 남는다. 픽업 제한과 추가비용·당일 상담 필요를 앞에 표시.</td></tr><tr><td>꽃다발 책 넘김과 클래스 현장사진 존재</td><td>설명과 현장 신뢰에 도움이 될 가능성이 있다. 책은 선택적으로 펼치고, 수업은 실제 현장을 보게 한다.</td></tr><tr><td>자동스크롤이 여러 선택에 적용</td><td>일부 고객에게 진행을 돕지만 연속 화면 이동은 위치를 잃게 할 수 있다. 명시적인 다음 선택에만 사용하고 감소 동작 설정 고려.</td></tr></table><p>픽셀 단위 브라우저 검수나 이탈률 측정 결과가 아닌, 소스 기반 UX 검토입니다.</p>\n<h2>2. 기능적·감정적·사회적 욕구</h2><table><tr><th>욕구</th><th>실제로 얻고 싶은 결과 — 가설</th><th>필요한 증거·기능</th></tr><tr><td>기능적</td><td>예산에 맞는 크기, 약속한 장소·일정에 수령, 상황에 맞는 구성, 설명 시간 절약</td><td>검증된 크기사진·가격·픽업/배송 조건·최종 총액·일정 확인</td></tr><tr><td>감정적</td><td>잘못 골랐다는 걱정을 줄이고, ‘내가 준비했다’는 안도감과 만족감</td><td>쉬운 요청 예시, 선택 수정, 사진과 실제 구성의 차이 안내, 부담 없는 상담</td></tr><tr><td>사회적</td><td>상대를 기억하는 사람, 예의를 갖춘 사람, 취향과 관심이 있는 사람으로 마음을 표현</td><td>받는 분의 취향·사용처 반영, 카드/리본, 행사에 맞는 선택 안내</td></tr></table><p>자기용 꽃에는 관계 표현보다 공간 취향과 일상의 즐거움이 중요할 수 있습니다. 근조 주문은 취향 과시보다 예의와 정확성이 우선이라는 가설로 별도 취급합니다.</p>\n<h2>3. 현재 모습과 되고 싶은 모습의 차이</h2><table><tr><th>구매 상황</th><th>현재 느끼는 차이 — 가설</th><th>되고 싶은 모습 — 가설</th><th>상품과 서비스가 돕는 범위</th></tr><tr><td>생일·감사 선물</td><td>마음은 있지만 무엇을 골라야 할지 모름</td><td>상대 취향과 날짜를 기억하는 사람</td><td>색감·사용처·메시지를 꽃과 카드로 구체화. 상대의 반응을 보장하지는 않음.</td></tr><tr><td>졸업·기념일</td><td>기념할 순간인데 준비가 막막함</td><td>중요한 날을 챙기는 사람</td><td>크기·예산·수령일 선택으로 준비 과정을 줄임. 사진과 함께 순간을 기록할 수 있음.</td></tr><tr><td>개업·인사이동</td><td>격식과 예산의 적정선을 모르겠음</td><td>관계를 세심하게 챙기는 사람</td><td>놓을 공간·메시지·관리조건을 확인한 상품 선택. 업무 성과나 평판 상승 보장은 불가.</td></tr><tr><td>웨딩·프로포즈</td><td>원하는 분위기는 있지만 구현 방법을 모름</td><td>우리다운 장면을 준비하는 사람</td><td>현장 조건·색감·연출 상담으로 취향을 시각화. 관계 성공과 상품 구매를 연결하지 않음.</td></tr><tr><td>자기용·클래스</td><td>취향을 즐기고 싶지만 경험이 적음</td><td>내 일상을 돌보고 직접 만들어보는 사람</td><td>꽃을 배치하거나 수업에서 작품을 만드는 구체적 경험. 심리치료 효과로 주장하지 않음.</td></tr></table>\n<h3>자기 이미지 카피 5개</h3><ol><li>소중한 사람을 잘 챙기고 싶은 날.</li><li>꽃 이름은 몰라도, 그 사람의 취향은 알고 있으니까.</li><li>큰 선물보다, 그 사람에게 어울리는 선물.</li><li>우리다운 순간을, 우리다운 꽃으로.</li><li>내 일상에도, 내가 좋아하는 꽃 한 자리.</li></ol><p>카피는 테스트 초안이며 전환 효과가 검증된 문구가 아닙니다. 2번은 상대 취향을 모르는 고객에게도 별도의 ‘함께 골라요’ 경로를 제공합니다.</p>\n<h2>4. 관심이 생기는 상황과 감정적 욕구</h2><table><tr><th>욕구</th><th>관심이 생기는 상황 — 가설</th><th>구매 가치 / 우선순위 가설</th></tr><tr><td>편안함</td><td>시간이 촉박하거나 꽃을 처음 고름</td><td>불확실성과 선택 부담을 줄임. 첫 구매의 우선 과제.</td></tr><tr><td>인정</td><td>감사 표현, 부모님 선물, 공식 행사</td><td>배려를 표현하고 알아주길 바람. 타인의 반응을 약속하지 않음.</td></tr><tr><td>자신감</td><td>예산·크기·스타일을 판단하기 어려움</td><td>내가 선택한 이유를 설명할 수 있음. 비교 정보가 우선.</td></tr><tr><td>성취감</td><td>행사 준비, 졸업 축하, 클래스 작품 완성</td><td>준비를 마치거나 직접 만든 결과를 확인.</td></tr><tr><td>소속감</td><td>가족 기념일, 모임, 함께하는 수업</td><td>함께하는 순간과 감사 표현에 참여. 꽃 구매가 소속의 조건은 아님.</td></tr></table>\n<h3>욕구별 판매 문구 — 각 3개</h3><h4>편안함</h4><ol><li>꽃 이름 대신, 전할 순간과 예산만 알려주세요.</li><li>픽업인지 배송인지, 받는 방법부터 확인해보세요.</li><li>고르기 어렵다면, 원하는 색감부터 함께 정해요.</li></ol><h4>인정</h4><ol><li>고마운 이유를 한 줄 남겨주세요. 꽃과 함께 전할 수 있어요.</li><li>그 사람이 좋아하는 색을, 이번 선물에 담아보세요.</li><li>기억하고 있다는 마음을, 그날의 꽃으로 전해보세요.</li></ol><h4>자신감</h4><ol><li>크기와 가격을 먼저 보고, 내 예산에 맞게 고르세요.</li><li>건네는 상황에 맞는 크기부터 살펴보세요.</li><li>꼭 원하는 꽃이 있다면, 제작 전에 가능 여부를 확인해보세요.</li></ol><h4>성취감</h4><ol><li>새로운 시작을 축하하는 꽃, 예산부터 차근차근 준비해보세요.</li><li>함께 정한 구성으로, 기다리던 날의 한 장면을 준비하세요.</li><li>내 손으로 완성한 꽃 한 작품. 클래스에서 시작해보세요.</li></ol><h4>소속감</h4><ol><li>함께 축하하는 자리에, 마음을 전할 꽃을 골라보세요.</li><li>우리 가족의 기념일에, 서로의 취향을 담아보세요.</li><li>꽃을 사이에 두고, 우리 모임의 시간을 만들어보세요.</li></ol>\n<h2>5. 갖고 싶은 이유를 합리적으로 판단하기</h2><table><tr><th>이유</th><th>동기 가설</th><th>실제 혜택·사용 가치</th><th>구매 판단 기준</th></tr><tr><td>희소성</td><td>계절감과 나에게 맞춘 구성이 특별하게 느껴질 수 있음</td><td>실제로 확보된 계절 소재·맞춤 색감이 있을 때만 유효</td><td>입고 가능 여부와 대체 소재를 확인. 희귀함만으로 추가 지출할 필요 없음. 한정 수량·마감 허위 표시 금지.</td></tr><tr><td>자기표현</td><td>나 또는 상대의 취향을 표현하고 싶음</td><td>색감, 크기, 카드 문구를 선택 가능</td><td>받는 분 취향과 공간에 맞는지, 요청이 제작 가능한지 확인.</td></tr><tr><td>편리함</td><td>방문·탐색·설명에 드는 시간을 줄이고 싶음</td><td>온라인 비교·픽업 선택·배송 상담</td><td>대전 안에서도 실제 이동 거리, 주차, 수령 시간, 배송비를 비교. 당일 가능 여부는 확인 전 보장하지 않음.</td></tr><tr><td>만족감</td><td>예상한 모습으로 선물하거나 감상하고 싶음</td><td>공간 장식·선물 전달·감상의 경험</td><td>최종 총액, 크기사진, 꽃 구성 변화, 관리 부담을 확인. 고가일수록 상대가 더 좋아한다고 단정하지 않음.</td></tr><tr><td>새로운 경험</td><td>직접 만들기·새로운 취향을 시도하고 싶음</td><td>클래스에서 배우고 만드는 과정, 결과물</td><td>수업시간·난이도·재료·인원·비용을 상담해 비교. 완제품만 필요하면 수업보다 완제품 구매가 맞을 수 있음.</td></tr></table>\n<h2>6. 새 홈페이지 설계</h2><ol><li><b>첫 화면:</b> ‘소중한 사람을 잘 챙기고 싶은 날’ + 바로 크기·가격 보기. 별도 입장 단계 생략.</li><li><b>상품 바로가기:</b> 이미 상품을 정한 사람의 동선을 유지.</li><li><b>상황 탐색:</b> 상품을 모르는 사람에게 생일·감사·졸업 등 선택 경로.</li><li><b>예산 비교:</b> S/M/L 상품 가격과 픽업 조건을 먼저 노출. 큰 사이즈 강요 없음.</li><li><b>제작사진:</b> 실제 제공 사진 사용. 확인되지 않은 사이즈 라벨을 붙이지 않음.</li><li><b>꽃다발 선택 도움:</b> 상황·예산·수령 기준의 단순 후보 제안. AI 진단·인기 순위처럼 포장하지 않음.</li><li><b>주문:</b> 크기/예산 → 스타일 → 제작 예시 → 수령/요청. 책 넘김 가이드는 필요할 때 펼침.</li><li><b>실무 불안 해소:</b> 당일 가능 여부·배송비·구성 변화·쇼핑백을 안내. 배송 총액 미확정 상태는 결제 완료처럼 표현하지 않음.</li><li><b>매장/관계:</b> 위치, 클래스, 비회원/회원 진입은 구매 흐름을 막지 않는 위치에 배치.</li></ol>\n<h2>7. 가설을 확인하는 방법</h2><p>대전 고객의 지역 자체보다 구매 목적·수령 조건·예산이 설명력이 높은지 먼저 확인합니다. 신규 고객 6~8명에게 생일·당일 픽업·공식 선물 과제를 제시해 탐색을 관찰하고, 결과는 탐색 자료로만 사용합니다.</p><ul><li>가격·수령 조건을 정확히 설명할 수 있는가?</li><li>같은 예산에서 스타일별 가격 차이를 이해하는가?</li><li>처음 망설인 지점과 결정을 도운 정보는 무엇인가?</li><li>실제 크기사진을 보았을 때 선택이 바뀌는가?</li><li>예산을 넘기는 추천으로 압박받는다고 느끼는가?</li></ul><p>운영 후에는 탐색 시작→상품 선택→수령 선택→상담/주문 완료를 비교합니다. 클릭 증가만으로 구매 효과를 결론내리지 않습니다. 취소·추가금 문의·기대와 실제 크기 차이도 함께 봅니다. 전환율 개선 수치는 현재 제시할 근거가 없습니다.</p>\n<h2>8. 참고한 일반 연구와 적용 한계</h2><p><a href=\"https://www.gsb.stanford.edu/faculty-research/publications/money-cant-buy-love-asymmetric-beliefs-about-link-between-gift-price\" target=\"_blank\" rel=\"noopener\">Flynn & Adams (2009), Money can’t buy love</a>: 선물 가격과 감사에 대한 주는 사람·받는 사람의 판단 차이를 다룬 연구. 높은 가격을 더 큰 사랑으로 연결하지 않는 설계에 참고했습니다.</p><p><a href=\"https://doi.org/10.1093/jcr/ucw067\" target=\"_blank\" rel=\"noopener\">Chan & Mogilner (2017), Experiential Gifts Foster Stronger Social Relationships Than Material Gifts</a>: 경험 선물과 관계 강화를 다룬 연구. 클래스 동기를 생각할 때 참고했으며 꽃다발 구매나 대전 고객에게 동일한 효과를 보장하지 않습니다.</p><p><strong>모든 지역 고객 심리·우선순위·카피 효과는 검증 전 가설입니다.</strong> 실제 사진의 사이즈 구분, 지도/채널 URL, 배송 조건, 운영 기능 연동은 별도 확인이 필요합니다.</p></article>\n";
